cenozoApp.defineModule({name:"apex_host",models:["add","list","view"],create:module=>{angular.extend(module,{identifier:{column:"name"},name:{singular:"apex host",plural:"apex hosts",possessive:"apex host's"},columnList:{name:{title:"name"},ssh_address:{title:"address"}},defaultOrder:{column:"apex_host.name",reverse:false}});module.addInputGroup("",{name:{title:"Name",type:"string"},ssh_address:{title:"SSH Address",type:"string"},ssh_username:{title:"SSH Username",type:"string",help:"No password is required since a keyfile is used instead."},db_address:{title:"MSSQL Address",type:"string"},db_username:{title:"MSSQL Username",type:"string",help:"The password is stored in the application's configuration file."}});module.addExtraOperation("view",{title:"Check Status",operation:async function($state,model){await model.viewModel.checkStatus()},isDisabled:function($state,model){return model.viewModel.checkingStatus}});cenozo.providers.factory("CnApexHostViewFactory",["CnBaseViewFactory","CnHttpFactory","CnModalMessageFactory",function(CnBaseViewFactory,CnHttpFactory,CnModalMessageFactory){var object=function(parentModel,root){CnBaseViewFactory.construct(this,parentModel,root,"image");angular.extend(this,{checkingStatus:false,checkStatus:async function(){this.checkingStatus=true;try{const response=await CnHttpFactory.instance({path:"apex_host/"+this.record.id,data:{select:{column:"status"}}}).get();const status=JSON.parse(response.data.status);let message="<ul>";for(let key in status){message+="<li>"+key+": "+(status[key]?"online":"offline")+"</li>"}message+="</ul>";await CnModalMessageFactory.instance({title:"Apex Host Status",message:message,html:true}).show()}finally{this.checkingStatus=false}}});async function init(object){await object.deferred.promise;if(angular.isDefined(object.imageModel)){object.imageModel.getChooseEnabled=function(){return false}}}init(this)};return{instance:function(parentModel,root){return new object(parentModel,root)}}}])}});
